package com.yihe.framework.ehr;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import javax.servlet.http.*;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.net.*;import java.io.*;import java.security.SecureRandom;import java.util.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/ai-models")
public class AiModelManagementApi{
 private final EhrAccess access;private final ModelRecognitionSettings recognition;private final HealthAgentSettings agent;private final ObjectMapper json=new ObjectMapper();
 @Value("${ehr.storage-root:${EHR_STORAGE_ROOT:D:/update}}") private String storage;
 @Value("${ehr.digital-worker.model-config-file:${EHR_DIGITAL_WORKER_CONFIG_FILE:}}") private String workerFile="";
 public AiModelManagementApi(EhrAccess a,ModelRecognitionSettings r,HealthAgentSettings h){access=a;recognition=r;agent=h;}@ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}
 private String s(Object v){return v==null?"":String.valueOf(v);}private void check(boolean b,String msg){if(!b)throw new EhrException(422,msg);}private void manage(EhrActor a){if(!a.doctor||a.mobile)throw new EhrException(403,"模型管理与测试需要医生管理权限");}
 private Path root(){return Paths.get(storage,".ai-model-management");}private Path file(EhrActor a){return root().resolve(Base64.getUrlEncoder().withoutPadding().encodeToString(digest(bytes(a.scope+":"+a.mode)))+".json");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object v,int max){check(v instanceof List&&((List<?>)v).size()<=max,"配置列表格式无效或超过限制");List<Map<String,Object>> out=new ArrayList<>();for(Object x:(List<?>)v){check(x instanceof Map,"配置行无效");out.add((Map<String,Object>)x);}return out;}
 @SuppressWarnings("unchecked") private Map<String,Object> read(EhrActor a)throws IOException{Path p=file(a);if(!Files.exists(p))return map("version",0,"models",new ArrayList<>(),"categories",new ArrayList<>(),"policy",map("fallback",false,"retries",0),"tests",new ArrayList<>());check(Files.size(p)<=4194304,"模型配置过大");return json.readValue(Files.readAllBytes(p),Map.class);}
 private void write(EhrActor a,Map<String,Object> state)throws IOException{byte[] data=json.writeValueAsBytes(state);check(data.length<=4194304,"模型配置超过4MB");Files.createDirectories(root());Path p=file(a),t=Files.createTempFile(root(),"models-",".tmp");try{Files.write(t,data);try{Files.move(t,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ex){Files.move(t,p,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(t);}}
 private byte[] master()throws Exception{Files.createDirectories(root());Path p=root().resolve(".credential-key");if(!Files.exists(p)){byte[] k=new byte[32];new SecureRandom().nextBytes(k);try{Files.write(p,k,StandardOpenOption.CREATE_NEW);}catch(FileAlreadyExistsException ignored){}}byte[] k=Files.readAllBytes(p);check(k.length==32,"密钥存储配置无效");return k;}
 private String crypt(EhrActor a,String id,String value,boolean encrypt){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");byte[] iv,content;if(encrypt){iv=new byte[12];new SecureRandom().nextBytes(iv);content=value.getBytes(StandardCharsets.UTF_8);}else{byte[] all=Base64.getDecoder().decode(value);iv=Arrays.copyOfRange(all,0,12);content=Arrays.copyOfRange(all,12,all.length);}c.init(encrypt?Cipher.ENCRYPT_MODE:Cipher.DECRYPT_MODE,new SecretKeySpec(master(),"AES"),new GCMParameterSpec(128,iv));c.updateAAD(bytes(a.scope+":"+a.mode+":"+id));byte[] out=c.doFinal(content);if(!encrypt)return new String(out,StandardCharsets.UTF_8);byte[] combined=new byte[iv.length+out.length];System.arraycopy(iv,0,combined,0,iv.length);System.arraycopy(out,0,combined,iv.length,out.length);return Base64.getEncoder().encodeToString(combined);}catch(Exception ex){throw new EhrException(500,"密钥存储不可用，请检查服务器配置");}}
 @SuppressWarnings("unchecked") private Map<String,Object> source(String id){try{if(id.equals("runtime-agent"))return agent.read();if(id.equals("runtime-ocr"))return recognition.read();if(id.equals("runtime-workers")&&!workerFile.trim().isEmpty()){Path p=Paths.get(workerFile);if(Files.isRegularFile(p)&&Files.size(p)<=16384)return json.readValue(Files.readAllBytes(p),Map.class);}}catch(Exception ignored){}return Collections.emptyMap();}
 private Map<String,Object> publicModel(Map<String,Object> m){Map<String,Object> out=new LinkedHashMap<>(m);out.remove("encryptedKey");out.remove("apiKey");out.put("hasKey",!s(m.get("encryptedKey")).isEmpty());out.put("readOnly",false);out.put("simulated",false);out.put("source","本组织保存的模型配置");return out;}
 private Map<String,Object> view(EhrActor a,Map<String,Object> state){Map<String,Object> out=new LinkedHashMap<>(state);List<Object> models=new ArrayList<>();for(Map<String,Object> m:rows(state.get("models"),100))models.add(publicModel(m));for(String id:Arrays.asList("runtime-workers","runtime-agent","runtime-ocr")){Map<String,Object> c=source(id);String endpoint=s(c.get("baseUrl"));try{URI u=URI.create(endpoint);if(u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)endpoint="";}catch(Exception ex){endpoint="";}boolean configured=!endpoint.isEmpty()&&!s(c.get("model")).isEmpty()&&!s(c.get("apiKey")).isEmpty();models.add(map("id",id,"name",id.equals("runtime-workers")?"数字员工运行模型":id.equals("runtime-agent")?"数字健康师运行模型":"报告识别运行模型","provider","现有服务","kind",id.equals("runtime-ocr")?"multimodal":"llm","baseUrl",endpoint,"modelId",s(c.get("model")),"apiStyle",s(c.getOrDefault("apiStyle",id.equals("runtime-workers")?"responses":"responses")),"deployment","cloud","version","","enabled",configured&&(id.equals("runtime-workers")||Boolean.TRUE.equals(c.get("enabled")))&&(!id.equals("runtime-ocr")||recognition.isModel()),"hasKey",!s(c.get("apiKey")).isEmpty(),"readOnly",true,"simulated",false,"source","现有运行配置（只读，不回传密钥）","scenarios",Arrays.asList(id.equals("runtime-ocr")?"report":id.equals("runtime-agent")?"consult":"other"),"description",id.equals("runtime-ocr")&&!recognition.isModel()?"当前报告识别使用已有OCR工作服务，未启用此模型接口。":"保留原业务配置；需独立登记时请复制后填写组织模型参数。"));}
 for(String[] sample:new String[][]{{"DeepSeek-V3","DeepSeek","llm"},{"Qwen2.5-VL","阿里云","multimodal"},{"PaddleOCR","百度飞桨","ocr"}})models.add(map("id","example-"+sample[0],"name",sample[0]+"（示例）","provider",sample[1],"kind",sample[2],"baseUrl","","modelId","","deployment","cloud","apiStyle","chat_completions","enabled",false,"hasKey",false,"readOnly",true,"simulated",true,"source","模拟数据来源：用户参考图，仅用于展示；未接入服务","scenarios",new ArrayList<>(),"description","展示示例不参与真实测试或业务调用，请新增真实模型配置。"));out.put("models",models);out.put("canManage",a.doctor&&!a.mobile);out.put("monitorSource","本页真实模型测试记录；不代表全平台调用总量");return out;}
 private void text(Map<String,Object> m,String k,int max,boolean required){check(s(m.get(k)).length()<=max&&(!required||!s(m.get(k)).trim().isEmpty()),"字段 "+k+" 为空或过长");}
 private URI endpoint(Map<String,Object> m,boolean resolve)throws Exception{URI u=new URI(s(m.get("baseUrl")));check(u.getHost()!=null&&u.getUserInfo()==null&&u.getQuery()==null&&u.getFragment()==null,"服务地址格式无效");check(u.getPath().matches("/?(?:v1|api)?/?"),"服务地址请填写根地址或/v1、/api，不包含具体调用路径");boolean cloud="cloud".equals(m.get("deployment"));check(cloud?"https".equals(u.getScheme()):Arrays.asList("http","https").contains(u.getScheme()),"云服务地址须使用HTTPS");if(resolve){for(InetAddress ip:InetAddress.getAllByName(u.getHost())){check(!ip.isLinkLocalAddress()&&!ip.isAnyLocalAddress()&&!ip.isMulticastAddress(),"不允许访问此类服务地址");if(cloud)check(!ip.isSiteLocalAddress()&&!ip.isLoopbackAddress(),"云服务地址不能指向内网或本机");else check(Arrays.asList(11434,1234,8000).contains(u.getPort()),"本地/私有服务仅支持11434、1234、8000端口");}}return u;}
 @GetMapping public synchronized Object get(HttpServletRequest r)throws IOException{EhrActor a=access.web(r);return ok(view(a,read(a)));}
 @PutMapping public synchronized Object save(HttpServletRequest req,@RequestBody Map<String,Object> body)throws IOException{EhrActor a=access.web(req);manage(a);Map<String,Object> old=read(a);if(EhrService.num(old.get("version"))!=EhrService.num(body.get("version")))throw new EhrException(409,"模型配置已更新，请刷新后重试");List<Map<String,Object>> models=rows(body.get("models"),100),categories=rows(body.get("categories"),100),previous=rows(old.get("models"),100);Set<String> ids=new HashSet<>();for(Map<String,Object> m:models){text(m,"id",100,true);text(m,"name",150,true);text(m,"modelId",150,true);text(m,"provider",150,false);text(m,"description",2000,false);text(m,"baseUrl",1000,true);check(!s(m.get("id")).startsWith("runtime-")&&!s(m.get("id")).startsWith("example-")&&ids.add(s(m.get("id"))),"模型标识重复或属于只读来源");check(Arrays.asList("llm","multimodal","ocr","medical","predictive","custom").contains(s(m.get("kind"))),"模型类型无效");check(Arrays.asList("cloud","local","private").contains(s(m.get("deployment"))),"部署类型无效");check(Arrays.asList("chat_completions","responses").contains(s(m.get("apiStyle"))),"接口协议无效");check(m.get("scenarios") instanceof List&&((List<?>)m.get("scenarios")).size()<=6,"应用场景无效");for(Object scenario:(List<?>)m.get("scenarios"))check(Arrays.asList("consult","report","plan","follow","education","other").contains(s(scenario)),"应用场景无效");double temperature=m.get("temperature") instanceof Number?((Number)m.get("temperature")).doubleValue():-1;check(Double.isFinite(temperature)&&temperature>=0&&temperature<=2,"温度须为0–2");check(m.get("maxTokens") instanceof Number&&EhrService.num(m.get("maxTokens"))>=16&&EhrService.num(m.get("maxTokens"))<=8192,"输出长度须为16–8192");check(m.get("timeoutSeconds") instanceof Number&&EhrService.num(m.get("timeoutSeconds"))>=1&&EhrService.num(m.get("timeoutSeconds"))<=60,"超时须为1–60秒");try{endpoint(m,false);}catch(EhrException ex){throw ex;}catch(Exception ex){throw new EhrException(422,"模型服务地址无效");}Map<String,Object> p=previous.stream().filter(x->s(x.get("id")).equals(s(m.get("id")))).findFirst().orElse(null);String key=s(m.remove("apiKey"));m.remove("encryptedKey");if(Boolean.TRUE.equals(m.remove("removeKey"))){m.put("encryptedKey","");}else if(!key.isEmpty()){check(key.length()<=4096&&!key.contains("\r")&&!key.contains("\n"),"API密钥格式无效");m.put("encryptedKey",crypt(a,s(m.get("id")),key,true));}else if(p!=null)m.put("encryptedKey",p.getOrDefault("encryptedKey",""));else m.put("encryptedKey","");m.remove("hasKey");m.remove("source");m.remove("readOnly");m.remove("simulated");}
 Set<String> categoryIds=new HashSet<>();for(Map<String,Object> c:categories){text(c,"id",100,true);text(c,"name",100,true);check(categoryIds.add(s(c.get("id"))),"分类标识重复");}check(body.get("policy") instanceof Map,"调用策略格式无效");Map<?,?> policy=(Map<?,?>)body.get("policy");check(policy.get("retries") instanceof Number&&EhrService.num(policy.get("retries"))>=0&&EhrService.num(policy.get("retries"))<=3,"重试次数须为0–3");for(String k:Arrays.asList("primaryId","fallbackId"))check(s(policy.get(k)).isEmpty()||ids.contains(s(policy.get(k))),"调用策略引用了不存在的组织模型");check(!Boolean.TRUE.equals(policy.get("fallback"))||!s(policy.get("fallbackId")).isEmpty(),"启用备用策略须选择备用模型");Map<String,Object> next=map("version",EhrService.num(old.get("version"))+1,"models",models,"categories",categories,"policy",policy,"tests",old.get("tests"));write(a,next);return ok(view(a,next));}
 @PostMapping("/test") public synchronized Object test(HttpServletRequest req,@RequestBody Map<String,Object> b)throws IOException{EhrActor a=access.web(req);manage(a);Map<String,Object> data=read(a),m=rows(data.get("models"),100).stream().filter(x->s(x.get("id")).equals(s(b.get("modelId")))).findFirst().orElse(null);Map<String,Object> config;String id=s(b.get("modelId"));if(m==null){check(Arrays.asList("runtime-workers","runtime-agent","runtime-ocr").contains(id),"请先保存真实模型，示例不能测试");config=new LinkedHashMap<>(source(id));check(!config.isEmpty(),"运行配置尚未就绪");config.put("deployment","cloud");config.put("modelId",config.get("model"));config.put("timeoutSeconds",15);config.put("name",id);config.putIfAbsent("apiStyle","responses");}else{config=new LinkedHashMap<>(m);check(!s(m.get("encryptedKey")).isEmpty()||!"cloud".equals(m.get("deployment")),"请先配置API密钥");config.put("apiKey",s(m.get("encryptedKey")).isEmpty()?"":crypt(a,id,s(m.get("encryptedKey")),false));}boolean inference="inference".equals(s(b.get("mode")));String path=inference?("responses".equals(s(config.get("apiStyle")))?"/responses":"/chat/completions"):"/models";long started=System.currentTimeMillis();HttpURLConnection conn=null;int status=0;String message="",output="";Object tokens=null;try{URI uri=endpoint(config,true);URL url=new URL(uri.toString().replaceAll("/+$","")+path);conn=(HttpURLConnection)url.openConnection();conn.setInstanceFollowRedirects(false);int timeout=Math.max(1000,Math.min(60000,EhrService.num(config.get("timeoutSeconds"))*1000));conn.setConnectTimeout(timeout);conn.setReadTimeout(timeout);conn.setRequestProperty("Accept","application/json");if(!s(config.get("apiKey")).isEmpty())conn.setRequestProperty("Authorization","Bearer "+config.get("apiKey"));if(inference){conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");Map<String,Object> payload="responses".equals(s(config.get("apiStyle")))?map("model",config.get("modelId"),"input","Reply only OK.","store",false,"max_output_tokens",16):map("model",config.get("modelId"),"messages",Arrays.asList(map("role","user","content","Reply only OK.")),"max_tokens",16);try(OutputStream os=conn.getOutputStream()){os.write(json.writeValueAsBytes(payload));}}status=conn.getResponseCode();message=status>=200&&status<300?(inference?"接口接受了功能测试请求":"模型列表接口可访问"):"服务返回HTTP "+status+"，请核对地址、协议、权限和密钥";if(status>=200&&status<300){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))>=0){if(out.size()+n>262144)throw new IOException();out.write(buf,0,n);}}if(inference){com.fasterxml.jackson.databind.JsonNode response=json.readTree(out.toByteArray());StringBuilder answer=new StringBuilder();if(response.has("choices"))answer.append(response.path("choices").path(0).path("message").path("content").asText(""));if(response.has("output_text"))answer.append(response.path("output_text").asText(""));for(com.fasterxml.jackson.databind.JsonNode item:response.path("output"))for(com.fasterxml.jackson.databind.JsonNode content:item.path("content"))if(content.has("text"))answer.append(content.path("text").asText());output=answer.toString();String credential=s(config.get("apiKey"));if(!credential.isEmpty())output=output.replace(credential,"[已隐藏密钥]");if(output.length()>200)output=output.substring(0,200);if(response.path("usage").has("total_tokens"))tokens=response.path("usage").path("total_tokens").asInt();if(output.trim().isEmpty()){message="接口有响应，但未返回可识别的文本，请核对协议和模型";status=422;}}}}catch(EhrException ex){throw ex;}catch(Exception ex){message="连接或响应解析失败，请核对服务地址、网络、协议及超时设置";status=0;}finally{if(conn!=null)conn.disconnect();}Map<String,Object> record=map("id",UUID.randomUUID().toString(),"modelId",id,"name",config.get("name"),"mode",inference?"inference":"connection","status",status,"success",status>=200&&status<300,"message",message,"latencyMs",System.currentTimeMillis()-started,"tokens",tokens,"createdAt",now()+"Z");List<Map<String,Object>> tests=rows(data.get("tests"),500);tests.add(record);if(tests.size()>200)tests=new ArrayList<>(tests.subList(tests.size()-200,tests.size()));data.put("tests",tests);data.put("version",EhrService.num(data.get("version"))+1);write(a,data);return ok(map("record",record,"output",output,"version",data.get("version")));}
}
